package com.campusevents.dao;
import com.campusevents.model.*;import com.campusevents.util.*;import java.sql.*;import java.util.*;
public class UserDAO {public User login(String email)throws SQLException{String q="SELECT u.*,s.student_id,s.college_id,s.department,s.academic_year,s.phone FROM users u LEFT JOIN students s ON s.user_id=u.user_id WHERE u.email=?";try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next())return null;if(r.getString("role").equals("ADMIN"))return new Admin(r.getInt("user_id"),r.getString("name"),r.getString("email"),r.getString("password_hash"));return new Student(r.getInt("user_id"),r.getInt("student_id"),r.getString("name"),r.getString("email"),r.getString("password_hash"),r.getString("college_id"),r.getString("department"),r.getInt("academic_year"),r.getString("phone"));}}}public void register(String name,String email,String hash,String college,String dept,int year,String phone)throws SQLException{try(Connection c=DatabaseConnection.get()){c.setAutoCommit(false);try{int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'STUDENT')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,hash);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO students(user_id,college_id,department,academic_year,phone) VALUES(?,?,?,?,?)")){p.setInt(1,id);p.setString(2,college);p.setString(3,dept);p.setInt(4,year);p.setString(5,phone);p.executeUpdate();}c.commit();}catch(SQLException e){c.rollback();throw e;}}}public List<String[]> students()throws SQLException{List<String[]> a=new ArrayList<>();try(Connection c=DatabaseConnection.get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT u.name,u.email,s.college_id,s.department,s.academic_year,s.phone FROM students s JOIN users u ON u.user_id=s.user_id ORDER BY u.name")){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)});}return a;}}
